cd /app && node << 'EOF'
const fs = require('fs');
const buf = fs.readFileSync('./a.out');

// Parse ELF header for 64-bit little-endian
const e_shoff = buf.readBigUInt64LE(40);
const e_shentsize = buf.readUInt16LE(58);
const e_shnum = buf.readUInt16LE(60);

// Find string table section (section header string table index is at offset 50)
const e_shstrndx = buf.readUInt16LE(50);
const strtab_offset = Number(e_shoff) + (e_shstrndx * e_shentsize);
const strtab_addr = buf.readBigUInt64LE(strtab_offset + 16);
const strtab_file_offset = buf.readBigUInt64LE(strtab_offset + 24);
const strtab_size = buf.readBigUInt64LE(strtab_offset + 32);

console.log('String table offset in file:', strtab_file_offset);
console.log('String table size:', strtab_size);

// Find .data and .rodata sections
console.log('\n=== Loadable Sections ===');
for (let i = 0; i < e_shnum; i++) {
  const offset = Number(e_shoff) + (i * e_shentsize);
  const sh_name = buf.readUInt32LE(offset);
  const sh_type = buf.readUInt32LE(offset + 4);
  const sh_flags = buf.readBigUInt64LE(offset + 8);
  const sh_addr = buf.readBigUInt64LE(offset + 16);
  const sh_offset = buf.readBigUInt64LE(offset + 24);
  const sh_size = buf.readBigUInt64LE(offset + 32);

  // Read section name from string table
  let name = '?';
  if (sh_name > 0 && sh_name < strtab_size) {
    const nameStart = Number(strtab_file_offset) + sh_name;
    const nameEnd = buf.indexOf(0, nameStart);
    if (nameEnd > nameStart) {
      name = buf.slice(nameStart, nameEnd).toString('utf8');
    }
  }

  // Show loadable sections
  if ((Number(sh_flags) & 2) !== 0) { // SHF_ALLOC
    console.log(`Section ${i}: name="${name}" addr=0x${sh_addr.toString(16).padStart(8, '0')}, offset=${sh_offset}, size=${sh_size}, flags=0x${sh_flags.toString(16)}`);
  }
}

